CREATE TABLE package (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE documents (name TEXT PRIMARY KEY, data BLOB NOT NULL);
CREATE TABLE records (path TEXT PRIMARY KEY, kind TEXT NOT NULL, canonical_id TEXT UNIQUE, owner_id TEXT);
CREATE INDEX records_kind ON records(kind, canonical_id);
CREATE INDEX records_owner ON records(owner_id);
CREATE TABLE children (parent TEXT NOT NULL REFERENCES records(path), slot TEXT NOT NULL, locator TEXT NOT NULL, child TEXT NOT NULL UNIQUE REFERENCES records(path), PRIMARY KEY(parent,slot,locator));
CREATE TABLE refs (parent TEXT NOT NULL REFERENCES records(path), slot TEXT NOT NULL, position INTEGER NOT NULL, target TEXT NOT NULL REFERENCES records(canonical_id), PRIMARY KEY(parent,slot,position));
CREATE INDEX refs_target ON refs(target);
CREATE TABLE geometry (id TEXT PRIMARY KEY, digest TEXT NOT NULL, raw_bytes INTEGER NOT NULL, data BLOB NOT NULL);
CREATE TABLE geometry_refs (source TEXT REFERENCES geometry(id), target TEXT REFERENCES geometry(id), PRIMARY KEY(source,target));
CREATE TABLE associations (position INTEGER PRIMARY KEY, domain_id TEXT NOT NULL REFERENCES records(canonical_id), geometry_id TEXT NOT NULL REFERENCES geometry(id), data TEXT NOT NULL);
